const byId = new Map(CATALOG.map(item => [item.id, item]));
const performanceModes = new Set(['balanced', 'eco', 'quality']);
const MAX_POINTS = 1e9;
const MAX_COORD = 1e7;
const isRecord = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const finite = value => typeof value === 'number' && Number.isFinite(value);
const safeInt = (value, min, max) => finite(value) && Number.isInteger(value) && value >= min && value <= max;
const cleanText = (value, fallback, length = 80) => typeof value === 'string' && value.trim() ? value.trim().slice(0, length) : fallback;
const coordinatesValid = (x, y) => safeInt(x, -MAX_COORD, MAX_COORD) && safeInt(y, -MAX_COORD, MAX_COORD);
const validTimestamp = value => finite(value) && value >= 0 && value <= 8640000000000000;
const cleanId = value => typeof value === 'string' ? value.trim().slice(0, 128) : '';
// States loaded from this browser remember their last persisted snapshot. This
// prevents a delayed storage event from letting an older tab overwrite progress.
// New and imported states deliberately remain eligible to replace a save.
const savedSnapshots = new WeakMap();
let idCounter = 0;
const makeId = () => globalThis.crypto?.randomUUID?.() || `${Date.now().toString(36)}-${(++idCounter).toString(36)}-${Math.random().toString(36).slice(2, 9)}`;

export function createInitialState(seed = Math.floor(Math.random() * 0xffffffff)) {
  return {
    version: 2,
    seed: safeInt(seed, 0, 0xffffffff) ? seed : 20261012,
    points: 0,
    buildings: {},
    checkins: createCheckinState(),
    sessions: [],
    focus: null,
    cityName: 'FocuCity',
    levelUnlocked: 1,
    settings: { sound: false, performanceMode: 'balanced' },
  };
}

export function localDateKey(date = new Date()) {
  const value = date instanceof Date ? date : new Date(date);
  return `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, '0')}-${String(value.getDate()).padStart(2, '0')}`;
}

function metrics(buildings) {
  let population = 0;
  let gdp = 0;
  let buildingCount = 0;
  for (const building of Object.values(buildings || {})) {
    const definition = byId.get(building?.type);
    if (!definition) continue;
    population += definition.population;
    gdp += definition.gdp;
    buildingCount += 1;
  }
  return { population, gdp, buildingCount };
}

export function levelByMetrics(buildings) {
  const { population, gdp } = metrics(buildings);
  return LEVELS.reduce((level, milestone) => population >= milestone.population || gdp >= milestone.gdp ? milestone.level : level, 1);
}

export function cityStats(state) {
  const current = metrics(state.buildings);
  const level = Math.max(levelByMetrics(state.buildings), Math.min(LEVELS.length, state.levelUnlocked || 1));
  const milestone = LEVELS[level - 1];
  const next = LEVELS[level];
  return {
    ...current,
    level,
    unlockedLevel: level,
    title: milestone.title,
    nextLevel: next?.level ?? null,
    nextPopulation: next?.population ?? null,
    nextGdp: next?.gdp ?? null,
    progress: next ? Math.min(1, Math.max(current.population / next.population, current.gdp / next.gdp)) : 1,
    maxLevel: !next,
  };
}

export function todayStats(state, date = new Date()) {
  const key = localDateKey(date);
  const sessions = state.sessions.filter(session => session.date === key);
  return {
    minutes: sessions.reduce((total, session) => total + session.minutes, 0),
    points: sessions.reduce((total, session) => total + session.points, 0),
    count: sessions.length,
    sessions,
  };
}

export function weekStats(state, date = new Date()) {
  const current = new Date(date);
  // Calendar arithmetic keeps this correct through daylight-saving changes.
  current.setHours(12, 0, 0, 0);
  return Array.from({ length: 7 }, (_, index) => {
    const day = new Date(current);
    day.setDate(current.getDate() - 6 + index);
    const { sessions, ...stats } = todayStats(state, day);
    return { date: localDateKey(day), label: `${day.getMonth() + 1}/${day.getDate()}`, weekday: ['日', '一', '二', '三', '四', '五', '六'][day.getDay()], today: index === 6, ...stats };
  });
}

export function getRemaining(state, now = Date.now()) {
  const focus = state.focus;
  if (!focus) return 0;
  if (!validTimestamp(now)) return Math.max(0, focus.remaining);
  return focus.status === 'running'
    ? Math.max(0, Math.min(focus.duration, Math.ceil((focus.endAt - now) / 1000)))
    : Math.max(0, focus.remaining);
}

export function startFocus(state, { task = '一件值得专注的小事', minutes = 25 } = {}, now = Date.now()) {
  if (state.focus) return { ok: false, message: '请先完成或结束当前专注。' };
  if (!safeInt(minutes, 1, 240) || !validTimestamp(now) || !validTimestamp(now + minutes * 60000)) return { ok: false, message: '专注时长请填写 1–240 分钟的整数。' };
  const duration = minutes * 60;
  state.focus = { id: makeId(), task: cleanText(task, '一件值得专注的小事'), duration, remaining: duration, endAt: now + duration * 1000, status: 'running' };
  return { ok: true, message: '专注已经开始。', focus: state.focus };
}

export function pauseFocus(state, now = Date.now()) {
  if (!validTimestamp(now)) return { ok: false, message: '计时信息无效，请重试。' };
  if (state.focus?.status !== 'running') return { ok: false, message: '当前没有正在进行的专注。' };
  const remaining = getRemaining(state, now);
  if (remaining === 0) {
    const completed = completeFocus(state, now);
    return { ok: true, message: '这一段专注已完成。', completed };
  }
  state.focus.remaining = remaining;
  state.focus.endAt = null;
  state.focus.status = 'paused';
  return { ok: true, message: '专注已暂停。' };
}

export function resumeFocus(state, now = Date.now()) {
  if (state.focus?.status !== 'paused') return { ok: false, message: '当前没有暂停的专注。' };
  if (!validTimestamp(now) || !validTimestamp(now + state.focus.remaining * 1000)) return { ok: false, message: '计时信息无效，请重试。' };
  state.focus.endAt = now + state.focus.remaining * 1000;
  state.focus.status = 'running';
  return { ok: true, message: '继续这一段专注。' };
}

export function cancelFocus(state) {
  if (!state.focus) return { ok: false, message: '当前没有专注任务。' };
  state.focus = null;
  return { ok: true, message: '本次专注已结束，未完成的专注不获得专注点。' };
}

export function completeFocus(state, now = Date.now()) {
  const focus = state.focus;
  if (!focus || focus.status !== 'running' || !validTimestamp(now) || !validTimestamp(focus.endAt) || now < focus.endAt) return null;
  // A saved or imported timer can never award the same session twice.
  if (state.sessions.some(session => session.id === focus.id)) {
    state.focus = null;
    return null;
  }
  const minutes = focus.duration / 60;
  const session = { id: focus.id, task: focus.task, minutes, points: minutes, completedAt: focus.endAt, date: localDateKey(focus.endAt) };
  state.points = Math.min(MAX_POINTS, state.points + minutes);
  state.sessions.push(session);
  state.focus = null;
  return { points: minutes, minutes, session };
}

function terrainName(terrain) {
  return typeof terrain === 'string' ? terrain : terrain?.type;
}

const waterTypes = new Set(['water', 'river', 'lake', 'ocean']);
const landTypes = new Set(['grass', 'forest']);
const rotationValue = rotation => rotation === 1 ? 1 : 0;

/** Stored dimensions are already rotated; old saves without dimensions occupy one cell. */
export function getFootprint(typeOrBuilding, x, y, rotation = 0) {
  let width = 1, height = 1;
  if (typeof typeOrBuilding === 'string') {
    const definition = byId.get(typeOrBuilding);
    if (!definition) return [];
    width = definition.width;
    height = definition.height;
    if (rotationValue(rotation)) [width, height] = [height, width];
  } else if (isRecord(typeOrBuilding)) {
    width = safeInt(typeOrBuilding.width, 1, 16) ? typeOrBuilding.width : 1;
    height = safeInt(typeOrBuilding.height, 1, 16) ? typeOrBuilding.height : 1;
  } else return [];
  return Array.from({ length: width * height }, (_, index) => ({ x: x + index % width, y: y + Math.floor(index / width) }));
}

export function getBuildingAt(state, x, y) {
  if (!coordinatesValid(x, y)) return null;
  for (const [key, building] of Object.entries(state.buildings || {})) {
    const definition = byId.get(building?.type);
    if (!definition) continue;
    const [bx, by] = key.split(',').map(Number);
    const width = safeInt(building.width, 1, 16) ? building.width : 1;
    const height = safeInt(building.height, 1, 16) ? building.height : 1;
    if (x >= bx && x < bx + width && y >= by && y < by + height) return { key, x: bx, y: by, building, definition };
  }
  return null;
}

// The original UI passed the anchor terrain and a neighbour callback. Accept
// that signature while new callers provide a terrain function for the entire lot.
function placementArguments(x, y, terrain, rotationOrNeighbor = 0, legacyRotation = 0) {
  if (typeof terrain === 'function') return { terrainAt: terrain, rotation: rotationValue(rotationOrNeighbor) };
  return {
    terrainAt: (cx, cy) => cx === x && cy === y ? terrain : typeof rotationOrNeighbor === 'function' ? rotationOrNeighbor(cx, cy) : terrain,
    rotation: rotationValue(typeof rotationOrNeighbor === 'function' ? legacyRotation : rotationOrNeighbor),
  };
}

function placementCheck(state, definition, x, y, terrainAt, rotation, ignoreKey = null) {
  if (!definition) return { ok: false, message: '没有找到这项设施。' };
  if (!coordinatesValid(x, y)) return { ok: false, message: '请选择有效的地块。' };
  const footprint = getFootprint(definition.id, x, y, rotation);
  if (footprint.some(cell => !coordinatesValid(cell.x, cell.y))) return { ok: false, message: '设施超出了可建设范围。' };
  if (definition.level > cityStats(state).level) return { ok: false, message: `城市达到 Lv.${definition.level} 后解锁${definition.name}。` };
  for (const cell of footprint) {
    const occupied = getBuildingAt(state, cell.x, cell.y);
    if (occupied && occupied.key !== ignoreKey) return { ok: false, message: '设施范围内已有建筑，请预留完整地块。' };
  }
  if (typeof terrainAt !== 'function') return { ok: false, message: '无法读取地形，请重试。' };
  const grounds = footprint.map(cell => terrainName(terrainAt(cell.x, cell.y)));
  if (definition.terrain === 'water') {
    if (!grounds.every(ground => waterTypes.has(ground))) return { ok: false, message: '桥梁需要架设在水面上。' };
  } else if (definition.terrain === 'mountain') {
    if (!grounds.every(ground => ground === 'mountain')) return { ok: false, message: '隧道需要建设在山区。' };
  } else if (definition.terrain === 'underground') {
    if (!grounds.every(ground => landTypes.has(ground) || waterTypes.has(ground) || ground === 'mountain')) return { ok: false, message: '这片地形无法铺设地铁线路。' };
  } else {
    if (!grounds.every(ground => landTypes.has(ground))) return { ok: false, message: `需要一整片 ${rotation ? definition.height : definition.width} × ${rotation ? definition.width : definition.height} 的草地或森林。` };
    if (definition.terrain === 'shore') {
      const occupiedCells = new Set(footprint.map(cell => `${cell.x},${cell.y}`));
      const nearWater = footprint.some(cell => [[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy]) => !occupiedCells.has(`${cell.x + dx},${cell.y + dy}`) && waterTypes.has(terrainName(terrainAt(cell.x + dx, cell.y + dy)))));
      if (!nearWater) return { ok: false, message: '港口需要建在紧邻水面的完整陆地上。' };
    }
  }
  return { ok: true, footprint, definition, rotation };
}

export function canBuildAt(state, id, x, y, terrain, rotationOrNeighbor = 0, legacyRotation = 0) {
  const args = placementArguments(x, y, terrain, rotationOrNeighbor, legacyRotation);
  const definition = byId.get(id);
  const result = placementCheck(state, definition, x, y, args.terrainAt, args.rotation);
  if (!result.ok) return result;
  if (!finite(state.points) || state.points < definition.cost) return { ok: false, message: `还差 ${Math.max(0, definition.cost - (state.points || 0))} 专注点，再专注一会儿吧。` };
  return { ...result, cost: definition.cost, message: '这片地块可以建设。' };
}

function storedBuilding(definition, rotation, paid = definition.cost) {
  return { type: definition.id, width: rotation ? definition.height : definition.width, height: rotation ? definition.width : definition.height, rotation, paid };
}

export function buildAt(state, id, x, y, terrain, rotationOrNeighbor = 0, legacyRotation = 0) {
  const result = canBuildAt(state, id, x, y, terrain, rotationOrNeighbor, legacyRotation);
  if (!result.ok) return result;
  state.points -= result.cost;
  state.buildings[`${x},${y}`] = storedBuilding(result.definition, result.rotation);
  const previousLevel = state.levelUnlocked || 1;
  state.levelUnlocked = Math.max(previousLevel, levelByMetrics(state.buildings));
  return { ok: true, message: `${result.definition.name}建好了！`, levelUp: state.levelUnlocked > previousLevel, level: state.levelUnlocked, cost: result.cost };
}

export function canUpgradeBuilding(state, x, y, terrainAt) {
  const existing = getBuildingAt(state, x, y);
  if (!existing) return { ok: false, message: '这里没有可以升级的设施。' };
  const definition = byId.get(existing.definition.upgradeTo);
  if (!definition) return { ok: false, message: '这项设施已经达到最高等级。' };
  const rotation = rotationValue(existing.building.rotation);
  const result = placementCheck(state, definition, existing.x, existing.y, terrainAt, rotation, existing.key);
  if (!result.ok) return { ...result, existing, definition };
  const paid = safeInt(existing.building.paid, 0, existing.definition.cost) ? existing.building.paid : existing.definition.cost;
  const cost = Math.max(0, definition.cost - paid);
  if (!finite(state.points) || state.points < cost) return { ok: false, message: `扩建还差 ${Math.max(0, cost - (state.points || 0))} 专注点。`, existing, definition, cost };
  return { ...result, existing, cost, message: `扩建为${definition.name}需要 ${cost} 专注点。` };
}

export function upgradeBuilding(state, x, y, terrainAt) {
  const result = canUpgradeBuilding(state, x, y, terrainAt);
  if (!result.ok) return result;
  state.points -= result.cost;
  state.buildings[result.existing.key] = storedBuilding(result.definition, result.rotation);
  const previousLevel = state.levelUnlocked || 1;
  state.levelUnlocked = Math.max(previousLevel, levelByMetrics(state.buildings));
  return { ok: true, message: `已扩建为${result.definition.name}！`, cost: result.cost, levelUp: state.levelUnlocked > previousLevel, level: state.levelUnlocked };
}

export function demolishAt(state, x, y) {
  if (!coordinatesValid(x, y)) return { ok: false, message: '请选择有效的地块。', refund: 0 };
  const existing = getBuildingAt(state, x, y);
  if (!existing) return { ok: false, message: '这里没有可以拆除的设施。', refund: 0 };
  state.levelUnlocked = cityStats(state).level;
  const paid = safeInt(existing.building.paid, 0, existing.definition.cost) ? existing.building.paid : existing.definition.cost;
  const refund = Math.floor(paid / 2);
  delete state.buildings[existing.key];
  state.points = Math.min(MAX_POINTS, state.points + refund);
  return { ok: true, message: `已拆除${existing.definition.name}，返还 ${refund} 专注点。`, refund };
}

export function validateSave(data) {
  if (!isRecord(data) || ![1, 2].includes(data.version) || !isRecord(data.buildings) || !Array.isArray(data.sessions)) {
    return { ok: false, message: '这不是有效的 FocuCity 存档，或存档版本不受支持。' };
  }
  const state = createInitialState(data.seed);
  state.cityName = cleanText(data.cityName, state.cityName, 24);
  state.points = safeInt(data.points, 0, MAX_POINTS) ? data.points : 0;
  state.settings.sound = data.settings?.sound === true;
  state.settings.performanceMode = performanceModes.has(data.settings?.performanceMode) ? data.settings.performanceMode : 'balanced';
  state.checkins = normalizeCheckins(data.checkins);
  const occupied = new Set();
  for (const [key, value] of Object.entries(data.buildings).slice(0, 100000)) {
    if (!/^-?\d+,-?\d+$/.test(key) || !isRecord(value) || !byId.has(value.type)) continue;
    const [x, y] = key.split(',').map(Number);
    if (!coordinatesValid(x, y)) continue;
    const definition = byId.get(value.type);
    const rotation = rotationValue(value.rotation);
    // v1 towns keep their original compact lots, even for now-larger facilities.
    const legacy = data.version === 1 || (value.width === undefined && value.height === undefined) || (value.width === 1 && value.height === 1);
    const expectedWidth = rotation ? definition.height : definition.width;
    const expectedHeight = rotation ? definition.width : definition.height;
    if (!legacy && (value.width !== expectedWidth || value.height !== expectedHeight)) continue;
    const building = { type: value.type, width: legacy ? 1 : expectedWidth, height: legacy ? 1 : expectedHeight, rotation, paid: safeInt(value.paid, 0, definition.cost) ? value.paid : definition.cost };
    const footprint = getFootprint(building, x, y);
    if (footprint.some(cell => !coordinatesValid(cell.x, cell.y) || occupied.has(`${cell.x},${cell.y}`))) continue;
    state.buildings[`${x},${y}`] = building;
    for (const cell of footprint) occupied.add(`${cell.x},${cell.y}`);
  }
  const knownIds = new Set();
  for (const session of data.sessions.slice(0, 100000)) {
    if (!isRecord(session)) continue;
    const id = cleanId(session.id);
    if (!id || knownIds.has(id)) continue;
    if (!safeInt(session.minutes, 1, 240) || !validTimestamp(session.completedAt)) continue;
    knownIds.add(id);
    state.sessions.push({ id, task: cleanText(session.task, '专注任务'), minutes: session.minutes, points: session.minutes, completedAt: session.completedAt, date: localDateKey(session.completedAt) });
  }
  const focus = data.focus;
  const focusId = cleanId(focus?.id);
  if (isRecord(focus) && focusId && !knownIds.has(focusId)
      && safeInt(focus.duration, 60, 240 * 60) && focus.duration % 60 === 0
      && safeInt(focus.remaining, 0, focus.duration)
      && ['running', 'paused'].includes(focus.status)
      && (focus.status === 'paused' || validTimestamp(focus.endAt))) {
    state.focus = {
      id: focusId, task: cleanText(focus.task, '专注任务'), duration: focus.duration,
      remaining: focus.remaining, endAt: focus.status === 'paused' ? null : focus.endAt, status: focus.status,
    };
  }
  const savedLevel = safeInt(data.levelUnlocked, 1, LEVELS.length) ? data.levelUnlocked : 1;
  // The original top level unlocked airports; preserve that earned unlock.
  const compatibleLevel = data.version === 1 && savedLevel === 5 ? 8 : savedLevel;
  state.levelUnlocked = Math.max(compatibleLevel, levelByMetrics(state.buildings));
  return { ok: true, state, message: '城市存档已准备好。' };
}

export function loadState() {
  try {
    const raw = globalThis.localStorage?.getItem(STORAGE_KEY) ?? null;
    const result = raw ? validateSave(JSON.parse(raw)) : null;
    const state = result?.ok ? result.state : createInitialState();
    savedSnapshots.set(state, raw);
    return state;
  } catch {
    return createInitialState();
  }
}

export function saveState(state) {
  try {
    if (!globalThis.localStorage) return { ok: false, message: '浏览器未提供本地存储，请导出存档保留进度。' };
    const current = globalThis.localStorage.getItem(STORAGE_KEY) ?? null;
    if (savedSnapshots.has(state) && savedSnapshots.get(state) !== current) {
      // An explicit import/reset creates an untracked state and can replace the
      // current snapshot. Ordinary UI edits must never replace another tab's work.
      let latest;
      try { latest = current ? validateSave(JSON.parse(current)) : null; } catch { /* Recover corrupt storage by saving this valid state. */ }
      if (latest?.ok) {
        Object.assign(state, latest.state);
        savedSnapshots.set(state, current);
        return { ok: false, conflict: true, message: '另一标签页有新进度，已同步城市，请重试刚才的操作。' };
      }
      if (current === null) {
        Object.assign(state, createInitialState());
        savedSnapshots.set(state, null);
        return { ok: false, conflict: true, message: '另一标签页已清除存档，当前城市已同步。' };
      }
    }
    const raw = JSON.stringify(state);
    globalThis.localStorage.setItem(STORAGE_KEY, raw);
    savedSnapshots.set(state, raw);
    return { ok: true, message: '城市已保存。' };
  } catch {
    return { ok: false, message: '本地存储空间不足或不可用，请导出存档保留进度。' };
  }
}
